class InteractionsNamespace {
  final ClientConfig _config;
  InteractionsNamespace(ClientConfig config) : _config = config;

  /// Shows which type of GitHub user can interact with this organization and when the restriction expires. If there is no restrictions, you will see an empty response.
  Future<dynamic> getRestrictionsForOrg(
      {required String org, RequestOptions? requestOptions}) async {
    return interactions_methods.interactionsGetRestrictionsForOrg(_config,
        org: org, requestOptions: requestOptions);
  }

  /// Temporarily restricts interactions to a certain type of GitHub user in any public repository in the given organization. You must be an organization owner to set these restrictions. Setting the interaction limit at the organization level will overwrite any interaction limits that are set for individual repositories owned by the organization.
  Future<InteractionLimitResponse> setRestrictionsForOrg(
      {required String org,
      required InteractionGroup limit,
      SdkOptional<InteractionExpiry> expiry = const SdkOmitted(),
      RequestOptions? requestOptions}) async {
    return interactions_methods.interactionsSetRestrictionsForOrg(_config,
        org: org, limit: limit, expiry: expiry, requestOptions: requestOptions);
  }

  /// Removes all interaction restrictions from public repositories in the given organization. You must be an organization owner to remove restrictions.
  Future<void> removeRestrictionsForOrg(
      {required String org, RequestOptions? requestOptions}) async {
    return interactions_methods.interactionsRemoveRestrictionsForOrg(_config,
        org: org, requestOptions: requestOptions);
  }

  /// Gets the pull request creation cap configuration for an organization. The cap limits the total number of open pull requests a user can have across all public repositories in the organization at one time. Only users with admin access to the organization can view the cap configuration.
  Future<InteractionsGetPullRequestCreationCapForOrgResponse>
      getPullRequestCreationCapForOrg(
          {required String org, RequestOptions? requestOptions}) async {
    return interactions_methods.interactionsGetPullRequestCreationCapForOrg(
        _config,
        org: org,
        requestOptions: requestOptions);
  }

  /// Updates the pull request creation cap for an organization. The cap limits the total number of open pull requests a user can have across all public repositories in the organization at one time. Only users with admin access to the organization can configure the cap.
  Future<InteractionsUpdatePullRequestCreationCapForOrgResponse>
      updatePullRequestCreationCapForOrg(
          {required String org,
          required bool enabled,
          SdkOptional<int> maxOpenPullRequests = const SdkOmitted(),
          SdkOptional<bool> includeDrafts = const SdkOmitted(),
          RequestOptions? requestOptions}) async {
    return interactions_methods.interactionsUpdatePullRequestCreationCapForOrg(
        _config,
        org: org,
        enabled: enabled,
        maxOpenPullRequests: maxOpenPullRequests,
        includeDrafts: includeDrafts,
        requestOptions: requestOptions);
  }

  /// Shows which type of GitHub user can interact with this repository and when the restriction expires. If there are no restrictions, you will see an empty response.
  Future<dynamic> getRestrictionsForRepo(
      {required String owner,
      required String repo,
      RequestOptions? requestOptions}) async {
    return interactions_methods.interactionsGetRestrictionsForRepo(_config,
        owner: owner, repo: repo, requestOptions: requestOptions);
  }

  /// Temporarily restricts interactions to a certain type of GitHub user within the given repository. You must have owner or admin access to set these restrictions. If an interaction limit is set for the user or organization that owns this repository, you will receive a `409 Conflict` response and will not be able to use this endpoint to change the interaction limit for a single repository.
