class MigrationsNamespace {
  final ClientConfig _config;
  MigrationsNamespace(ClientConfig config) : _config = config;

  /// Lists the most recent migrations, including both exports (which can be started through the REST API) and imports (which cannot be started using the REST API). A list of `repositories` is only returned for export migrations.
  Future<List<Migration>> listForOrg(
      {required String org,
      SdkOptional<int> perPage = const SdkOmitted(),
      SdkOptional<int> page = const SdkOmitted(),
      SdkOptional<List<MigrationsListForOrgExcludeItem>> exclude =
          const SdkOmitted(),
      RequestOptions? requestOptions}) async {
    return migrations_methods.migrationsListForOrg(_config,
        org: org,
        perPage: perPage,
        page: page,
        exclude: exclude,
        requestOptions: requestOptions);
  }

  /// Starts an organization migration to generate a migration archive. Supply `repositories` to select the repositories to include; the other boolean options default to false when omitted. Set `org_metadata_only` to true and provide an empty `repositories` list to include only organization metadata; a 201 response returns the migration record.
  ///
  /// Initiates the generation of a migration archive.
  Future<Migration> startForOrg(
      {required String org,
      required List<String> repositories,
      SdkOptional<bool> lockRepositories = const SdkOmitted(),
      SdkOptional<bool> excludeMetadata = const SdkOmitted(),
      SdkOptional<bool> excludeGitData = const SdkOmitted(),
      SdkOptional<bool> excludeAttachments = const SdkOmitted(),
      SdkOptional<bool> excludeReleases = const SdkOmitted(),
      SdkOptional<bool> excludeOwnerProjects = const SdkOmitted(),
      SdkOptional<bool> orgMetadataOnly = const SdkOmitted(),
      SdkOptional<List<MigrationsStartForOrgRequestBodyExcludeItem>> exclude =
          const SdkOmitted(),
      RequestOptions? requestOptions}) async {
    return migrations_methods.migrationsStartForOrg(_config,
        org: org,
        repositories: repositories,
        lockRepositories: lockRepositories,
        excludeMetadata: excludeMetadata,
        excludeGitData: excludeGitData,
        excludeAttachments: excludeAttachments,
        excludeReleases: excludeReleases,
        excludeOwnerProjects: excludeOwnerProjects,
        orgMetadataOnly: orgMetadataOnly,
        exclude: exclude,
        requestOptions: requestOptions);
  }

  /// Fetches the status of a migration. The `state` of a migration can be one of the following values: * `pending`, which means the migration hasn't started yet. * `exporting`, which means the migration is in progress. * `exported`, which means the migration finished successfully. * `failed`, which means the migration failed.
  Future<Migration> getStatusForOrg(
      {required String org,
      required int migrationId,
      SdkOptional<List<MigrationsGetStatusForOrgExcludeItem>> exclude =
          const SdkOmitted(),
      RequestOptions? requestOptions}) async {
    return migrations_methods.migrationsGetStatusForOrg(_config,
        org: org,
        migrationId: migrationId,
        exclude: exclude,
        requestOptions: requestOptions);
  }

  /// Retrieves the download URL for an organization's migration archive. Identify the migration with `org` and `migration_id`; the response redirects to the archive URL.
  ///
  /// Fetches the URL to a migration archive.
  Future<void> downloadArchiveForOrg(
      {required String org,
      required int migrationId,
      RequestOptions? requestOptions}) async {
    return migrations_methods.migrationsDownloadArchiveForOrg(_config,
        org: org, migrationId: migrationId, requestOptions: requestOptions);
  }

  /// Deletes a previous migration archive. Migration archives are automatically deleted after seven days.
  Future<void> deleteArchiveForOrg(
      {required String org,
      required int migrationId,
      RequestOptions? requestOptions}) async {
    return migrations_methods.migrationsDeleteArchiveForOrg(_config,
        org: org, migrationId: migrationId, requestOptions: requestOptions);
  }

  /// Unlocks a repository that was locked for migration. You should unlock each migrated repository and [delete them](https://docs.github.com/rest/repos/repos#delete-a-repository) when the migration is complete and you no longer need the source data.
  Future<void> unlockRepoForOrg(
      {required String org,
      required int migrationId,
      required String repoName,
      RequestOptions? requestOptions}) async {
    return migrations_methods.migrationsUnlockRepoForOrg(_config,
        org: org,
        migrationId: migrationId,
        repoName: repoName,
        requestOptions: requestOptions);
  }

  /// List all the repositories for this organization migration.
  Future<List<MinimalRepository>> listReposForOrg(
      {required String org,
      required int migrationId,
      SdkOptional<int> perPage = const SdkOmitted(),
      SdkOptional<int> page = const SdkOmitted(),
      RequestOptions? requestOptions}) async {
    return migrations_methods.migrationsListReposForOrg(_config,
        org: org,
        migrationId: migrationId,
        perPage: perPage,
        page: page,
